import sqlite3

def status_breakdown(con, table):
    cols = [r[1] for r in con.execute(f'PRAGMA table_info("{table}")')]
    if "status" in cols:
        return dict(con.execute(f'SELECT status, COUNT(*) FROM "{table}" GROUP BY status'))
    return None

for name in ("source", "target"):
    con = sqlite3.connect(f"file:databases/{name}.db?mode=ro", uri=True)
    print(f"== {name}.db")
    for t in ("orders", "orders_archive"):
        cols = [r[1] for r in con.execute(f'PRAGMA table_info("{t}")')]
        mn, mx = con.execute(f'SELECT MIN(id), MAX(id) FROM "{t}"').fetchone()
        n, nd = con.execute(f'SELECT COUNT(*), COUNT(DISTINCT id) FROM "{t}"').fetchone()
        print(f"  {t}: cols={cols} rows={n} distinct_ids={nd} id_range=({mn},{mx})")
        print(f"    status breakdown: {status_breakdown(con, t)}")
    overlap = con.execute('SELECT COUNT(*) FROM (SELECT id FROM orders INTERSECT SELECT id FROM orders_archive)').fetchone()[0]
    print(f"  id overlap orders∩orders_archive: {overlap}")
    con.close()
EOF"}

