{"command":"cd /testbed/migration-recon && python - <<'EOF'
import sqlite3, hashlib

def table_hash(con, table):
    cols = [r[1] for r in con.execute(f'PRAGMA table_info("{table}")')]
    rows = con.execute(f'SELECT {",".join(cols)} FROM "{table}" ORDER BY {",".join(cols)}').fetchall()
    h = hashlib.sha256()
    for row in rows:
        h.update(repr(row).encode() + b"\n")
    return h.hexdigest()[:16], len(rows)

results = {}
for name in ("source", "target"):
    con = sqlite3.connect(f"file:databases/{name}.db?mode=ro", uri=True)
    for t in ("customers", "orders", "orders_archive", "order_items", "payments", "addresses"):
        h, n = table_hash(con, t)
        results.setdefault(t, {})[name] = (h, n)
    con.close()

for t, d in results.items():
    same = d["source"][0] == d["target"][0] and d["source"][1] == d["target"][1]
    print(f"{t:15} source={d['source'][1]:>6} target={d['target'][1]:>6} content_identical={same}")
EOF"}

